#!/usr/bin/env python3
# Cumulative Patcher: Pristine Reconstructed PS5 13.60 Kernel -> Final Bootable QEMU Image (WP1..WP32)
# Input MD5 : 488414ba12dae305091401cab5342735
# Output MD5: 520808c90b58241f454baeae0db0c8cc
import base64, hashlib, os, sys, zlib

PRISTINE_MD5 = "488414ba12dae305091401cab5342735"
TARGET_MD5   = "520808c90b58241f454baeae0db0c8cc"
DIFF_B64     = ""

def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "wp3_boot/kernel_raw.bin"
    buf = bytearray(open(path, "rb").read())
    for off, chunk in eval(zlib.decompress(base64.b64decode(DIFF_B64))):
        buf[off : off + len(chunk)] = chunk
    open(path, "wb").write(buf)
    md5 = hashlib.md5(buf).hexdigest()
    print(f"[+] Patched {path} -> MD5: {md5}")
    assert md5 == TARGET_MD5, f"Expected {TARGET_MD5}, got {md5}"

if __name__ == "__main__":
    main()
